This function calculates the product A' * A, where A is the product of the symmetric block diagonal matrix "diag" and the kronecker product of lower triangular "L" and an identity matrix.
kron_diag_quad_form <- nimbleFunction(
  run = function(L = double(2), diag = double(3)){
    returnType(double(2))
    diag_dim <- dim(diag)
    T <- diag_dim[2]
    K <- diag_dim[3]
    KT <- K*T
    kdqf <- matrix(double(0, KT^2, init=FALSE), ncol=T)

    for (kr in 1:K){
      kr_step <- (kr-1)*T
      for (kc in 1:(kr-1)){
        kc_step <- (kc-1)*T
        kdqf_sub <- L[kr,kr] * L[kr,kc] * diag[1:T,1:T,kr]
        for (kj in (kr+1):K){
          kdqf_sub <- kdqf_sub + L[kj,kr] * L[kj,kc] * diag[1:T,1:T,kj]
        }
        kdqf[(kr_step+1):(kr_step+T),(kc_step+1):(kc_step+T)] <- kdqf_sub
        kdqf[(kc_step+1):(kc_step+T),(kr_step+1):(kr_step+T)] <- kdqf_sub
      }
      kdqf_sub <- L[kr,kr]^2 * diag[kr]
      for (kj in (kr+1):K){
        kdqf_sub <- kdqf_sub + L[kj,kr]^2 * diag[1:T,1:T,kj]
      }
      kdqf[(kr_step+1):(kr_step+T),(kr_step+1):(kr_step+T)] <- kdqf_sub
    }
    return(kdqf)
  }
)

Trying to compile the model gives me the following error:

defining model...
Error in genVarInfo3() :

  Dimension of Li_K is 2, which does not match its usage in 'fullPrecision <- kron_diag_quad_form(Li_K, ARarray)'.

I tried a couple iterations of moving pieces within the function off into other functions, but it did not help.

For example, attempting to follow pdevalpine's approach:

calculate_off_sub_matrix <- nimbleFunction(
  run = function(v1 = double(1), v2 = double(1), diag = double(3)){
    returnType(double(2))
    T = dim(diag)[1]
    kdqf_sub <- (v1[1] * v2[1]) * diag[1:T,1:T,1];
    for (i in 2:length(v1)){
      kdqf_sub <- kdqf_sub + (v1[i] * v2[i]) * diag[1:T,1:T,i];
    }
    return(kdqf_sub)
  }
)
calculate_on_sub_matrix <- nimbleFunction(
  run = function(v = double(1), diag = double(3)){
    returnType(double(2))
    T = dim(diag)[1]
    kdqf_sub <- (v[1]^2) * diag[1:T,1:T,1];
    for (i in 2:length(v)){
      kdqf_sub <- kdqf_sub + (v[i]^2) * diag[1:T,1:T,i];
    }
    return(kdqf_sub)
  }
)

kron_diag_quad_form <- nimbleFunction(
  run = function(L = double(2), diag = double(3)){
    returnType(double(2))
    diag_dim <- dim(diag)
    T <- diag_dim[2]
    K <- diag_dim[3]
    KT <- K*T;

    for (kr in 1:K){
      kr_step <- (kr-1)*T;
      for (kc in 1:(kr-1)){
        kc_step <- (kc-1)*T;
        kdqf_sub <- calculate_off_sub_matrix(L[kr:K,kr], L[kr:K,kc], diag[1:T,1:T,kr:K])
        kdqf[(kr_step+1):(kr_step+T),(kc_step+1):(kc_step+T)] <- kdqf_sub;
        kdqf[(kc_step+1):(kc_step+T),(kr_step+1):(kr_step+T)] <- kdqf_sub;
      }
      kdqf_sub <- calculate_on_sub_matrix(L[kr:K,kr], diag[1:T,1:T,kr:K])
      kdqf[(kr_step+1):(kr_step+T),(kr_step+1):(kr_step+T)] <- kdqf_sub;
    }
    return(kdqf);
  }
)

but got the same error.

I find this error bizarre. If the function is somehow implying that `kron = double(2)` is anything other than the explicitly stated `double(2)`, I'd hope defining the function would immediately throw an error -- for it not to wait until compiling the model.

